parameters.jsCode:
// Turns tenders and job postings into one signal schema and scores them.
// Schema: signalType, organisation, title, location, date, deadline, url, score (+ reason, signalId, found_at)
const HIGH_IF_DEADLINE_WITHIN_DAYS = 21; // tender with offer deadline < 21 days = high
const HIGH_IF_JOBS_PER_COMPANY = 3;      // >= 3 new roles at one company = high
const LEADERSHIP = /\b(head of|director|vp|vice president|chief|country manager|general manager)\b/i;

const lookback = $('Settings').first().json.lookbackDays || ($now.weekday === 1 ? 4 : 2);
const now = new Date();
const daysUntil = d => (d ? Math.ceil((new Date(d) - now) / 86400000) : null);
const clean = s => String(s || '').replace(/\s+/g, ' ').trim();
const rows = $input.all().map(i => i.json);
const foundAt = $now.toFormat('yyyy-MM-dd');
const signals = [];

// 1) Public tenders (service.bund.de)
for (const t of rows.filter(r => r.tenderId && r.url)) {
  const due = t.deadline || t.publicationEnd || '';
  const left = daysUntil(due);
  if (left !== null && left < 0) continue; // already closed
  const high = left !== null && left < HIGH_IF_DEADLINE_WITHIN_DAYS;
  signals.push({
    signalId: 'tender:' + t.url,
    found_at: foundAt,
    signalType: 'public_tender',
    organisation: clean(t.contractingAuthority),
    title: clean(t.title),
    location: [t.city, t.state].filter(Boolean).join(', ') || clean(t.location),
    date: String(t.publishedAt || '').slice(0, 10),
    deadline: String(due).slice(0, 10),
    url: t.url,
    score: high ? 'high' : 'medium',
    reason: left === null ? 'no deadline published'
      : `${left} day(s) to ${t.deadline ? 'offer deadline' : 'end of publication'}`,
  });
}

// 2) Hiring signals (company career sites)
const jobs = rows.filter(r => r.jobId && r.url && r.title);
const perCompany = {};
for (const j of jobs) perCompany[j.company] = (perCompany[j.company] || 0) + 1;
for (const j of jobs) {
  const n = perCompany[j.company];
  const score = n >= HIGH_IF_JOBS_PER_COMPANY ? 'high' : (LEADERSHIP.test(j.title) || n === 2 ? 'medium' : 'low');
  signals.push({
    signalId: 'job:' + j.url,
    found_at: foundAt,
    signalType: 'hiring',
    organisation: clean(j.company),
    title: clean(j.title),
    location: clean(j.location).slice(0, 120),
    date: String(j.postedAt || '').slice(0, 10),
    deadline: '',
    url: j.url,
    score,
    reason: `${n} role(s) posted at ${clean(j.company)} in the last ${lookback} day(s)`,
  });
}

const order = { high: 0, medium: 1, low: 2 };
signals.sort((a, b) => order[a.score] - order[b.score]);
return signals.map(s => ({ json: s }));

// Drops every signal whose signalId is already in the Google Sheets log.
const seen = new Set($input.all().map(i => String(i.json.signalId || '')).filter(Boolean));
return $('Normalize & score').all()
  .filter(i => !seen.has(i.json.signalId))
  .map(i => ({ json: i.json }));

// One Slack message per morning: high signals first, then a count of the rest.
const SHOW = 10;
const signals = $input.all().map(i => i.json);
if (signals.length === 0) return [];
const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\|/g, '-');
const count = (k, v) => signals.filter(s => s[k] === v).length;
const label = { public_tender: 'Tender', hiring: 'Hiring' };
let text = `*Sales signals*: ${signals.length} new (${count('score', 'high')} high, ${count('score', 'medium')} medium, ${count('score', 'low')} low)\n`;
text += `${count('signalType', 'public_tender')} public tender(s), ${count('signalType', 'hiring')} job posting(s)\n`;
const top = signals.filter(s => s.score !== 'low').slice(0, SHOW);
for (const s of top) {
  const due = s.deadline ? ` - due ${s.deadline}` : '';
  text += `\n[${s.score}] ${label[s.signalType] || s.signalType}: *${esc(s.organisation)}* - <${s.url}|${esc(s.title).slice(0, 110)}>${due}\n    _${esc(s.reason)}_`;
}
const rest = signals.length - top.length;
if (rest > 0) text += `\n\n...and ${rest} more in the sheet`;
return [{ json: { text } }];
